// Pattern Break Watchlist data — chart patterns being tracked per stock.
// Percentages in the UI are measured from `price` (the close on `priceDate`),
// not from the stock file's `currentPrice`.
//
// direction: "down" | "up" | "both" ("both" = no break yet; uses breakUp/breakDown/goalUp/goalDown)
// stage:     "forming" | "signal" | "confirmed" | "target" | "failed" | "update"
//            "update" = needs updating: a pending setup closed past one of its limits;
//            prevStage / updateDate / updateNote record what it was, when, and what broke
//            (set by pattern_watchlist.py; stageDate keeps the date of the previous stage).

export type PatternDirection = 'up' | 'down' | 'both';
/** 'retest' is a confirmed break that has come back to the broken boundary and is
 *  being tested. It behaves as confirmed everywhere -- same levels, same target and
 *  failure checks -- and only reads differently. See PATTERN_RULES.md section 1. */
/** 'atRisk' is a confirmed break whose price has closed back past its own invalidation,
 *  once. Failure needs a follow-through close, so the break is not dead -- but it is no
 *  longer working, and the row says so. The price run sets it and clears it again if the
 *  next close comes back inside; prevStage / updateDate hold what it was and when it went. */
export type PatternStage = 'forming' | 'signal' | 'confirmed' | 'retest' | 'atRisk' | 'target' | 'failed' | 'update';
export type PatternTimeframe = 'daily' | 'weekly' | 'monthly';
/** Direction of the stock's own trend, from ~3 months of daily bars (pattern_watchlist._trend).
 *  Setups pointing the same way are listed first; 'flat' leaves the stored order alone. */
export type PatternTrend = 'up' | 'down' | 'flat';

// Optional trendline anchors for the chart: [date 'YYYY-MM-DD', price] pairs.
export type PatternLine = { from: [string, number]; to: [string, number] };

// Stored setups in the same direction whose target is within 5% (computed by pattern_watchlist.py).
export type PatternAgree = { n: number; lo: number; hi: number; with: string[] };

export interface PatternAltSetup {
  auto?: boolean;
  agree?: PatternAgree;
  pattern?: string;
  timeframe: PatternTimeframe;
  flag?: string;
  direction: PatternDirection;
  stage: PatternStage;
  stageDate?: string;
  prevStage?: PatternStage;
  updateDate?: string;
  updateNote?: string;
  signal?: number;
  confirm?: number;
  invalidation?: number;
  target?: number;
  breakUp?: number;
  breakDown?: number;
  goalUp?: number;
  goalDown?: number;
  signalRule?: string;
  confirmRule?: string;
  failRule?: string;
  note?: string;
  lines?: PatternLine[];
}

export interface PatternHistoryEntry {
  pattern: string;
  timeframe: PatternTimeframe;
  direction: 'up' | 'down';
  stage: PatternStage;
  stageDate: string;
  confirm: number;
  invalidation: number;
  target: number;
  note?: string;
}

export interface PatternStock {
  ticker: string;
  name: string;
  auto?: boolean;              // auto-detected by pattern_detect.py: red dot until checked by hand
  trend?: PatternTrend;        // the stock's own trend; orders the setup list
  rsi?: number;                // daily Wilder RSI-14; >=60 bullish, <=40 bearish momentum
  agree?: PatternAgree;
  pattern: string;
  timeframe: PatternTimeframe;
  flag?: string;
  tag?: string;
  direction: PatternDirection;
  stage: PatternStage;
  stageDate?: string;
  prevStage?: PatternStage;
  updateDate?: string;
  updateNote?: string;
  price: number;
  priceDate: string;
  signal?: number;
  confirm?: number;
  invalidation?: number;
  target?: number;
  breakUp?: number;
  breakDown?: number;
  goalUp?: number;
  goalDown?: number;
  signalRule?: string;
  confirmRule?: string;
  failRule?: string;
  note?: string;
  lines?: PatternLine[];
  keyLevel?: { price: number; text: string };
  alt?: PatternAltSetup;
  history?: PatternHistoryEntry[];
  // Up to 5 setups are stored per stock; only the most valid (the main one) is shown.
  // The rest feed the "N agree" confidence badge when their targets match.
  more?: PatternAltSetup[];
}

